ALTER TABLE "player_decks" ADD CONSTRAINT "player_decks_cards_card" FOREIGN KEY ("card_id") REFERENCES "cards" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, ADD CONSTRAINT "player_decks_players_player" FOREIGN KEY ("player_id") REFERENCES "players" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION;
-- Modify "player_favorite_cards" table
ALTER TABLE "player_favorite_cards" ADD CONSTRAINT "player_favorite_cards_cards_card" FOREIGN KEY ("card_id") REFERENCES "cards" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, ADD CONSTRAINT "player_favorite_cards_players_player" FOREIGN KEY ("player_id") REFERENCES "players" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION;
